"""Generate synthetic fixtures for jump_replays.sp on a dedicated test server."""
import argparse
import base64
from pathlib import Path

# Synthetic account 12345, kz_test_jump; no production player data.
FIXTURE = ""
UNSUPPORTED = ""
LEGACY = ""

parser = argparse.ArgumentParser(__doc__)
parser.add_argument("root", type=Path, help="Dedicated test server's data/gokz-replays/_jumps path")
parser.add_argument("--load-count", type=int, default=0, help="Optional number of empty scan fixtures")
args = parser.parse_args()
args.root.mkdir(parents=True, exist_ok=True)
for name, content in [("totally-arbitrary.replay", FIXTURE), ("unsupported.replay", UNSUPPORTED), ("compat-legacy/12345/0_VNL_NRM.replay", LEGACY)]:
    path = args.root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(content))
link = args.root / "compat-link.replay"
link.unlink(missing_ok=True)
link.symlink_to((args.root / "totally-arbitrary.replay").resolve())
if args.load_count:
    load = args.root / "compat-load"
    load.mkdir(exist_ok=True)
    for index in range(args.load_count):
        (load / f"{index}.replay").touch()
print(f"Synthetic replay fixtures ready in {args.root.resolve()}")
